import {requestLocal,stepLocal} from './local-deal-20261010.js';
const $=id=>document.getElementById(id);
const fmt=n=>Number(n).toLocaleString('zh-CN',{maximumFractionDigits:2,minimumFractionDigits:0});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=null, token=null, selectedCharacter=0, selectedStock=0, selectedTarget=null, selectedCard=null, trading=false, playingCard=false, draggingCard=null, streamController=null, toastTimer, connected=false;
const signature={};
const accountSnapshots=new Map();
async function request(url,body){return requestLocal(url,body);}
function toast(text){$('toast').textContent=text;$('toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),3500);}
function show(id,visible=true){$(id).classList.toggle('hidden',!visible);}
function syncHTML(id,html){if(signature[id]!==html){$(id).innerHTML=html;signature[id]=html;}}
function portrait(character,mood=0,extra=''){return `<div class="portrait ${extra}" data-char="${character}" data-mood="${mood}"></div>`;}
function mood(kind){return {neutral:0,happy:1,panic:2,determined:3}[kind]||0;}
function timer(ms){const s=Math.ceil(ms/1000);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function renderCharacters(characters){$('characters').innerHTML=characters.map((c,i)=>`<button class="character-choice ${i===selectedCharacter?'selected':''}" data-character="${i}" title="${esc(c.bio)}">${portrait(i)}<strong>${c.name}</strong><small>${c.title}</small></button>`).join('');}
const info=await request('/api/info'); renderCharacters(info.characters); $('lanAddresses').textContent=info.addresses.length?`主机地址：${info.addresses.join(' / ')}`:'切走页面自动暂停 · 刷新后开始新局';
$('characters').addEventListener('click',e=>{const b=e.target.closest('[data-character]');if(b){selectedCharacter=Number(b.dataset.character);renderCharacters(info.characters);}});
async function enter(mode){try{const result=await request('/api/enter',{mode,character:selectedCharacter,code:$('roomCode').value});accountSnapshots.clear();token=result.token;sessionStorage.setItem('chart-duel-token',token);selectedCard=null;selectedTarget=null;selectedStock=0;signature.hand='';show('lobby',false);state=result.state;render();openStream();}catch(e){toast(e.message);}}
$('practice').onclick=()=>enter('practice');$('create').onclick=()=>enter('create');$('join').onclick=()=>enter('join');
async function action(a){try{state=await request('/api/action',a);render();return true;}catch(e){toast(e.message);return false;}}
function openStream(){streamController?.abort();streamController=new AbortController();connected=true;$('connection').textContent='● 单人对机器人';const interval=setInterval(()=>{state=stepLocal();if(state)render();},250);streamController.signal.addEventListener('abort',()=>clearInterval(interval));render();}
function backToLobby(){accountSnapshots.clear();streamController?.abort();token=null;sessionStorage.removeItem('chart-duel-token');state=null;selectedCard=null;show('lobby');for(const id of ['game','waiting','ended'])show(id,false);$('roomLabel').textContent='DEMO / 01';$('timer').textContent='08:00';$('connection').textContent='本地试玩';}
$('again').onclick=backToLobby;$('leaveWaiting').onclick=backToLobby;
document.querySelector('.brand').onclick=e=>{e.preventDefault();backToLobby();};
$('startRoom').onclick=()=>action({type:'start',fillBots:true});$('helpButton').onclick=()=>show('help');
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>show(b.dataset.close,false));
document.querySelectorAll('.overlay').forEach(el=>el.addEventListener('click',e=>{if(e.target===el&&['help'].includes(el.id))show(el.id,false);}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){['help'].forEach(id=>show(id,false));selectedCard=null;if(state)render();}});
function spark(candles){const a=candles.slice(-26).map(c=>c.close),low=Math.min(...a),high=Math.max(...a),range=high-low||1;const points=a.map((v,i)=>`${(i/(a.length-1)*74).toFixed(1)},${(28-(v-low)/range*26).toFixed(1)}`).join(' ');return `<svg class="spark" viewBox="0 0 75 30"><polyline points="${points}" fill="none" stroke="${a.at(-1)>=a[0]?'#e36f83':'#54a690'}" stroke-width="1.3"/></svg>`;}
function cardHTML(c,draft=false){const def=state.cardDefs[c.type],selected=!draft&&c.id===selectedCard;const target=state.players.find(p=>p.id===selectedTarget);const destination=def.target==='self'?'自己':def.target==='stock'?state.stocks[selectedStock].name:`${target?state.characters[target.character].name:'选择对手'} · ${state.stocks[selectedStock].name}`;return `<button class="card ${def.color} ${selected?'selected':''}" data-${draft?'pick':'card'}="${c.id}" title="${esc(def.text)}" ${!draft?`draggable="false" aria-pressed="${selected}"`:''}><span class="icon">${def.icon}</span><strong>${def.name}</strong>${selected?`<span class="card-confirm">${playingCard?'出牌中…':'确认出牌'}</span>`:''}<small>${esc(draft?'点击选择':selected?`→ ${destination}`:def.target==='stock'?'对当前股票':def.allowSelf?'对自己 / 对手':def.target==='rival'?'对选中对手':'保护自己')}</small></button>`;}

function accountHTML(player){const snapshot=accountSnapshots.get(player.id);if(!snapshot||state.now>=snapshot.at+3000)return '';return `<div class="account-inline"><div class="account-cash"><span>现金 <b>${fmt(snapshot.cash)}</b></span><span>可用 <b>${fmt(snapshot.available)}</b></span></div>${state.stocks.map((stock,i)=>`<div class="account-stock"><span>${stock.name}</span><b class="${snapshot.holdings[i]?'held':''}">${snapshot.holdings[i]}股</b></div>`).join('')}<small class="account-note">${snapshot.frozen?'资金冻结 · ':''}${snapshot.locked?'部分锁仓 · ':''}${snapshot.shield?'有豁免 · ':''}${new Date(snapshot.at).toLocaleTimeString('zh-CN')} 查询快照</small></div>`;}

function render(){if(!state||draggingCard)return;show('lobby',false);$('roomLabel').textContent=`房间 ${state.roomCode}`;$('timer').textContent=timer(state.remaining);
  if(state.state==='lobby'){show('waiting');show('game',false);$('waitingCode').textContent=state.roomCode;syncHTML('waitingPlayers',state.players.map(p=>`<div class="waiting-player">${portrait(p.character)}<b>${state.characters[p.character].name}</b><small>${p.id===state.me.id?'你':p.bot?'机器人':'已加入'}</small></div>`).join(''));show('startRoom',state.owner);return;}
  show('waiting',false);show('game');const stock=state.stocks[selectedStock],me=state.me;if(me.scan)accountSnapshots.set(me.scan.target,me.scan);
  if(!selectedTarget||!state.players.some(p=>p.id===selectedTarget))selectedTarget=state.players.find(p=>p.id!==me.id)?.id;
  if(selectedCard&&!me.hand.some(c=>c.id===selectedCard))selectedCard=null;
  syncHTML('stocks',state.stocks.map((s,i)=>{const change=(s.price/(s.referencePrice||s.candles[0].open)-1)*100;return `<button class="stock ${i===selectedStock?'active':''}" data-stock="${i}"><strong>${s.name}</strong>${spark(s.candles)}<b class="${change>=0?'up':'down'}">${s.price.toFixed(2)}</b><div class="stock-footer"><small class="${change>=0?'up':'down'}">${change>=0?'+':''}${change.toFixed(2)}%</small><span class="stock-holding ${me.holdings[i]?'has-holding':''}">持有 ${me.holdings[i]}股</span></div></button>`;}).join(''));
  $('stockName').textContent=stock.name;$('stockPrice').textContent=stock.price.toFixed(2);const ch=(stock.price/(stock.referencePrice||stock.candles[0].open)-1)*100;$('stockPrice').className=ch>=0?'up':'down';$('stockChange').className=ch>=0?'up':'down';$('stockChange').textContent=`${ch>=0?'+':''}${ch.toFixed(2)}%`;
  const self=state.players.find(p=>p.id===me.id);$('netWorth').textContent=fmt(self.value);$('cash').textContent=`现金 ${fmt(me.cash)} · 可用 ${fmt(me.available)}`;$('holding').textContent=`${stock.name} ${me.holdings[selectedStock]}股${me.locks[selectedStock]?` · 锁定${me.locks[selectedStock]}股`:''}`;
  const mp=$('myPortrait');mp.dataset.char=me.character;mp.dataset.mood=mood(self.reaction.kind);const reactionKey=`${self.reaction.kind}-${self.reaction.until}`;if(mp.dataset.reactionKey!==reactionKey){mp.className=`my-portrait portrait reaction-${self.reaction.kind}`;mp.dataset.reactionKey=reactionKey;}$('mySpeech').textContent=self.reaction.text;
  syncHTML('opponents',state.players.filter(p=>p.id!==me.id).map(p=>`<div class="opponent ${p.id===selectedTarget?'selected':''} ${p.frozen?'frozen':''} reaction-${p.reaction.kind}" data-target="${p.id}"><div class="portrait" data-char="${p.character}" data-mood="${mood(p.reaction.kind)}"><span class="speech">${esc(p.reaction.text)}</span></div><div class="opponent-info"><strong>${state.characters[p.character].name}</strong><small>${p.bot?'机器人':'真人'} · 手牌${p.handCount}张</small><b>${fmt(p.value)}</b>${p.frozen?`<small class="badge">❄ 冻结 ${Math.ceil(p.freezeRemaining/1000)}s</small>`:p.shield?'<small class="badge">◇ 豁免护盾</small>':''}<button data-scan="${p.id}" ${me.queryRemaining?'disabled':''}>⌕ ${accountSnapshots.has(p.id)?'刷新账户':'查账户'}${me.queryRemaining?` ${Math.ceil(me.queryRemaining/1000)}s`:''}</button></div>${accountHTML(p)}</div>`).join(''));
  $('handCount').textContent=`${me.hand.length} / 6`;syncHTML('hand',me.hand.length?me.hand.map(c=>cardHTML(c)).join(''):'<div class="empty-hand">暂时没有手牌，等待下一次自动补牌。</div>');
  syncHTML('attacks',state.attacks.filter(a=>a.target===me.id).map(a=>`<div class="attack"><span>⚠</span><b>${state.cardDefs[a.type].name} · ${state.stocks[a.stock].name}</b><span class="count">${Math.max(0,(a.due-state.now)/1000).toFixed(1)}秒后生效</span><button data-resist="${a.id}" ${me.hand.some(c=>c.type==='exempt')?'':'disabled'}>${me.hand.some(c=>c.type==='exempt')?'抵抗 · 消耗豁免':'没有豁免牌'}</button></div>`).join(''));
  $('marketEffect').textContent=Math.abs(stock.pressure)>.002?`行情受干预 ${stock.pressure>0?'↗':'↘'}`:'';
  syncHTML('logs',state.logs.slice(0,6).map(l=>`<div class="log-entry">${esc(l.text)}</div>`).join(''));
  document.getElementById("dealHint").textContent=me.hand.length>=6?'手牌已满':Math.ceil(state.nextDraft/1000)+'秒后补牌';
  if(state.state==='ended'){show('ended');syncHTML('results',[...state.players].sort((a,b)=>b.value-a.value).map((p,i)=>`<div class="result-row"><strong>${i+1}</strong>${portrait(p.character,i===0?1:0)}<span>${state.characters[p.character].name}<br><small>${p.id===me.id?'你':p.bot?'机器人':'真人'}</small></span><b>${fmt(p.value)}</b></div>`).join(''));}
  updateEstimate();drawChart();
}
$('stocks').onclick=e=>{const b=e.target.closest('[data-stock]');if(b){selectedStock=Number(b.dataset.stock);render();}};
$('opponents').onclick=async e=>{const scan=e.target.closest('[data-scan]');if(scan){selectedTarget=scan.dataset.scan;await action({type:'scan',target:scan.dataset.scan});return;}const target=e.target.closest('[data-target]');if(target){selectedTarget=target.dataset.target;render();}};
async function playHandCard(id,stock=selectedStock,target=selectedTarget){if(playingCard||!connected||state?.state!=='playing')return;playingCard=true;render();try{if(await action({type:'play',cardId:id,stock,target})){if(selectedCard===id)selectedCard=null;}}finally{playingCard=false;if(state)render();}}
$('hand').onclick=e=>{const b=e.target.closest('[data-card]');if(!b||playingCard||Date.now()<ignoreCardClickUntil)return;const id=b.dataset.card;if(selectedCard!==id){selectedCard=id;render();return;}playHandCard(id);};
$('myPortrait').onclick=()=>{const card=state?.me.hand.find(c=>c.id===selectedCard);if(card&&(state.cardDefs[card.type].allowSelf||state.cardDefs[card.type].target==='self')){selectedTarget=state.me.id;render();}};
function dropDestination(element){const card=state?.me.hand.find(c=>c.id===draggingCard);if(!card)return null;const def=state.cardDefs[card.type];const rival=element.closest('[data-target]'),self=element.closest('#myPortrait'),stock=element.closest('[data-stock]'),chart=element.closest('.chart-panel');if(def.target==='rival'&&rival)return {element:rival,target:rival.dataset.target,stock:selectedStock};if((def.allowSelf||def.target==='self')&&self)return {element:self,target:state.me.id,stock:selectedStock};if(def.target==='stock'&&(stock||chart))return {element:stock||chart,target:selectedTarget,stock:stock?Number(stock.dataset.stock):selectedStock};return null;}
function endCardDrag(){draggingCard=null;document.body.classList.remove('dragging-card');document.querySelectorAll('.drop-ready').forEach(el=>el.classList.remove('drop-ready'));if(state)render();}
let pointerDrag=null,ignoreCardClickUntil=0;
const dragGhost=document.createElement('div');dragGhost.className='card-drag-ghost hidden';document.body.append(dragGhost);
$('hand').addEventListener('pointerdown',e=>{const b=e.target.closest('[data-card]');if(!b||playingCard||!connected||state?.state!=='playing'||e.button!==0)return;draggingCard=b.dataset.card;pointerDrag={id:draggingCard,pointer:e.pointerId,x:e.clientX,y:e.clientY,active:false};});
document.addEventListener('pointermove',e=>{if(!pointerDrag||e.pointerId!==pointerDrag.pointer)return;if(!pointerDrag.active&&Math.hypot(e.clientX-pointerDrag.x,e.clientY-pointerDrag.y)<8)return;if(!pointerDrag.active)$('hand').setPointerCapture(e.pointerId);pointerDrag.active=true;document.body.classList.add('dragging-card');const card=state.me.hand.find(c=>c.id===draggingCard);dragGhost.textContent=state.cardDefs[card.type].name;dragGhost.classList.remove('hidden');dragGhost.style.left=`${e.clientX+12}px`;dragGhost.style.top=`${e.clientY+12}px`;document.querySelectorAll('.drop-ready').forEach(el=>el.classList.remove('drop-ready'));const destination=dropDestination(document.elementFromPoint(e.clientX,e.clientY));if(destination)destination.element.classList.add('drop-ready');});
document.addEventListener('pointerup',e=>{if(!pointerDrag||e.pointerId!==pointerDrag.pointer)return;const active=pointerDrag.active,id=pointerDrag.id,destination=active?dropDestination(document.elementFromPoint(e.clientX,e.clientY)):null;pointerDrag=null;dragGhost.classList.add('hidden');if(!active){draggingCard=null;return;}ignoreCardClickUntil=Date.now()+300;endCardDrag();if(destination){selectedStock=destination.stock;selectedTarget=destination.target;playHandCard(id,destination.stock,destination.target);}});
document.addEventListener('pointercancel',()=>{pointerDrag=null;dragGhost.classList.add('hidden');endCardDrag();});

document.addEventListener('click',e=>{if(selectedCard&&!playingCard&&!e.target.closest('#hand,#stocks,#opponents,#myPortrait,button,input')){selectedCard=null;if(state)render();}});
$('attacks').onclick=e=>{const b=e.target.closest('[data-resist]');if(b)action({type:'resist',attackId:b.dataset.resist});};
function quantity(){return Number($('quantity').value);}
function updateEstimate(){if(!state)return;const price=state.stocks[selectedStock].actualPrice;const canBuy=Math.floor(state.me.available/price),canSell=state.me.holdings[selectedStock]-state.me.locks[selectedStock];$('tradeEstimate').textContent=`预计 ${fmt(price*quantity())} · 可买 ${canBuy}股 · 可卖 ${canSell}股`;const busy=trading||!connected||state.state!=='playing';$('buy').disabled=$('sell').disabled=busy;document.querySelectorAll('[data-trade-fraction]').forEach(b=>{const capacity=b.dataset.side==='buy'?state.me.available/price:canSell;b.disabled=busy||Math.floor(capacity*Number(b.dataset.tradeFraction))<1;});}
$('quantity').oninput=updateEstimate;$('minus').onclick=()=>{$('quantity').value=Math.max(1,quantity()-100);updateEstimate();};$('plus').onclick=()=>{$('quantity').value=Math.min(1000000,quantity()+100);updateEstimate();};
async function submitTrade(side,fraction){if(!state||trading||!connected||state.state!=='playing')return;const q=quantity();if(fraction===undefined&&(!Number.isInteger(q)||q<1))return toast('请输入正整数股数');const stock=selectedStock;trading=true;updateEstimate();try{await action({type:'trade',side,stock,...(fraction===undefined?{quantity:q}:{fraction})});}finally{trading=false;updateEstimate();}}
$('buy').onclick=()=>submitTrade('buy');$('sell').onclick=()=>submitTrade('sell');
document.querySelectorAll('[data-trade-fraction]').forEach(b=>b.onclick=()=>submitTrade(b.dataset.side,Number(b.dataset.tradeFraction)));
const canvas=$('chart'),ctx=canvas.getContext('2d');let hover=-1;
function drawChart(){if(!state||state.state==='lobby')return;const rect=canvas.getBoundingClientRect(),dpr=devicePixelRatio||1;if(!rect.width)return;canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);const w=rect.width,h=rect.height,left=10,right=51,top=16,bottom=36,pw=w-left-right,ph=h-top-bottom;const bars=state.stocks[selectedStock].candles.slice(-65);let low=Math.min(...bars.map(c=>c.low)),high=Math.max(...bars.map(c=>c.high));const padding=Math.max((high-low)*.12,1);low-=padding;high+=padding;const y=v=>top+(high-v)/(high-low)*ph;ctx.clearRect(0,0,w,h);ctx.font='10px Segoe UI';ctx.textAlign='left';for(let i=0;i<6;i++){const yy=top+i*ph/5;ctx.strokeStyle='#323b4d';ctx.lineWidth=.6;ctx.beginPath();ctx.moveTo(left,yy);ctx.lineTo(w-right,yy);ctx.stroke();ctx.fillStyle='#8e9ab3';ctx.fillText((high-i*(high-low)/5).toFixed(2),w-right+9,yy+4);}const step=pw/bars.length,cw=Math.max(2,Math.min(8,step*.62));bars.forEach((c,i)=>{const x=left+(i+.5)*step,color=c.close>=c.open?'#e87c89':'#66b39d';ctx.strokeStyle=color;ctx.fillStyle=color;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,y(c.high));ctx.lineTo(x,y(c.low));ctx.stroke();ctx.fillRect(x-cw/2,Math.min(y(c.open),y(c.close)),cw,Math.max(1,Math.abs(y(c.open)-y(c.close))));});const price=state.stocks[selectedStock].price;ctx.setLineDash([4,4]);ctx.strokeStyle='#69738a';ctx.beginPath();ctx.moveTo(left,y(price));ctx.lineTo(w-right,y(price));ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#8e9ab3';ctx.textAlign='center';for(let i=0;i<5;i++){const x=left+(i+.5)*pw/5;ctx.fillText(`−${Math.round((4-i)*bars.length*(state.candleMs/1000)/5)}s`,x,h-10);}if(hover>=0&&hover<bars.length){const c=bars[hover],x=left+(hover+.5)*step;ctx.strokeStyle='#d0c6ed';ctx.beginPath();ctx.moveTo(x,top);ctx.lineTo(x,h-bottom);ctx.stroke();$('chartHover').textContent=`开 ${c.open.toFixed(2)} / 高 ${c.high.toFixed(2)} / 低 ${c.low.toFixed(2)} / 收 ${c.close.toFixed(2)}`;show('chartHover');}}
canvas.onmousemove=e=>{const r=canvas.getBoundingClientRect(),n=state?.stocks[selectedStock].candles.slice(-65).length||0;hover=Math.floor((e.clientX-r.left-10)/(r.width-61)*n);drawChart();};canvas.onmouseleave=()=>{hover=-1;show('chartHover',false);drawChart();};new ResizeObserver(drawChart).observe(canvas);
if(token){try{state=await request('/api/state');render();openStream();}catch{backToLobby();}}
